/*
  Slightly stiff bead-necklace polymer (from "Knot Dynamics") in a
  spherical container that is slowly compressed; watch how polymer
  attempts to pack optimally.
  Total kinetic energy is periodically rescaled to the nominal
  temperature (current value optionally shown).
  Image size varies with horizontal rotation. Click button to restart.

  No. 9 in "Chain Dynamics" series; others listed in "Knot Dynamics" (ttKXzc)
*/

#define VAR_ZERO min (nFrame, 0)

vec2 Rot2D (vec2 q, float a);
mat3 StdVuMat (float el, float az);
mat3 DirToRMatT (vec3 vd, vec3 vu);
vec3 HsvToRgb (vec3 c);
float ShowInt (vec2 q, vec2 cBox, float mxChar, float val);
vec4 Loadv4 (int idVar);

const int lenChain = 800;
vec3 vnObj, ltDir;
float dstFar, tCur, spRad;
int nFrame, idBall;
const float pi = 3.1415927;

#define AA  0     // (= 0/1) optional antialiasing
#define TUBE 1    // (= 0/1) show balls/tubes

#if TUBE

float CapsHit (vec3 ro, vec3 rd, float rad, float len)
{
  vec3 s;
  float dMin, d, a, b, w;
  dMin = dstFar;
  a = dot (rd.xy, rd.xy);
  b = dot (rd.xy, ro.xy);
  w = b * b - a * (dot (ro.xy, ro.xy) - rad * rad);
  if (w > 0. && a > 0.) {
    d = - b - sqrt (w);
    d /= a;
    s = ro + d * rd;
    if (d > 0. && abs (s.z) < len) {
      dMin = d;
      vnObj = vec3 (s.xy, 0.);
    } else {
      ro.z -= len * sign (s.z);
      b = dot (rd, ro);
      w = b * b - (dot (ro, ro) - rad * rad);
      if (w > 0.) {
        d = - b - sqrt (w);
        if (d > 0.) {
          dMin = d;
          vnObj = ro + d * rd;
        }
      }
    }
  }
  return dMin;
}

float PolyHit (vec3 ro, vec3 rd)
{
  mat3 rMat, rMatS;
  vec3 r, rp, vnObjS;
  float dMin, d, sz;
  sz = 0.45;
  dMin = dstFar;
  idBall = -1;
  for (int n = VAR_ZERO; n < lenChain; n ++) {
    if (n == 0) r = Loadv4 (0).xyz;
    else {
      rp = r;
      r = Loadv4 (2 * n).xyz;
      rMat = DirToRMatT (normalize (r - rp), vec3 (0., 0., 1.));
      d = CapsHit ((ro - 0.5 * (r + rp)) * rMat, rd * rMat, sz, 0.5 * length (r - rp));
      if (d < dMin) {
        dMin = d;
        rMatS = rMat;
        vnObjS = vnObj;
        idBall = n;
      }
    }
  }
  if (idBall >= 0) vnObj = rMatS * normalize (vnObjS);
  return dMin;
}

#else

float BallHit (vec3 ro, vec3 rd)
{
  vec3 v;
  float b, d, w, dMin, sz;
  dMin = dstFar;
  sz = 0.55;
  idBall = -1;
  for (int n = VAR_ZERO; n < lenChain; n ++) {
    v = ro - Loadv4 (2 * n).xyz;
    b = dot (rd, v);
    w = b * b + sz * sz - dot (v, v);
    if (w >= 0.) {
      d = - b - sqrt (w);
      if (d > 0. && d < dMin) {
        dMin = d;
        idBall = n;
      }
    }
  }
  if (idBall >= 0) vnObj = (ro - Loadv4 (2 * idBall).xyz + dMin * rd) / sz;
  return dMin;
}

#endif

vec4 SphHit (vec3 ro, vec3 rd, float rad)
{
  vec3 vn;
  float b, d, w;
  b = dot (rd, ro);
  w = b * b + rad * rad - dot (ro, ro);
  d = dstFar;
  if (w >= 0.) {
    d = - b - sqrt (w);
    vn = (ro + d * rd) / rad;
  }
  return vec4 (d, vn);
}

vec3 ShowScene (vec3 ro, vec3 rd)
{
  vec4 d4;
  vec3 col, vnSph;
  float dstObj, dstExtSph, h;
  d4 = SphHit (ro, rd, spRad);
  dstExtSph = d4.x;
  col = vec3 (0.5, 0.5, 0.7) * (0.3 + 0.1 * rd.y);
  if (dstExtSph < dstFar) {
#if TUBE
    dstObj = PolyHit (ro, rd);
#else   
    dstObj = BallHit (ro, rd);
#endif
    if (dstObj < dstFar) {
      h = mod (0.7 * float (idBall) / float (lenChain), 1.);
      col = HsvToRgb (vec3 (h, 1., 0.8)) * (0.3 + 0.7 * max (dot (vnObj, ltDir), 0.)) +
         0.2 * pow (max (dot (reflect (ltDir, vnSph), rd), 0.), 32.);
    }
    vnSph = d4.yzw;
    col += 0.02 + 0.05 * max (dot (ltDir, vnSph), 0.) +
       0.15 * pow (max (dot (reflect (ltDir, vnSph), rd), 0.), 64.);
  }
  return clamp (col, 0., 1.);
}

void mainImage (out vec4 fragColor, in vec2 fragCoord)
{
  mat3 vuMat;
  vec4 mPtr, stDat;
  vec3 rd, ro, col, wgBxC, c;
  vec2 canvas, uv, uvv;
  float asp, el, az, zmFac, sr, spRadB, kTemp;
  canvas = iResolution.xy;
  uv = 2. * fragCoord.xy / canvas - 1.;
  uv.x *= canvas.x / canvas.y;
  tCur = iTime;
  nFrame = iFrame;
  asp = canvas.x / canvas.y;
  wgBxC = vec3 (0.48 * asp, -0.46, 0.02);
  stDat = Loadv4 (2 * lenChain + 1);
  mPtr.xyz = stDat.xyz;
  stDat = Loadv4 (2 * lenChain);
  spRad = stDat.y;
  spRadB = stDat.z;
  kTemp = stDat.w;
  dstFar = 20. * spRad;
  az = 0.;
  el = -0.1 * pi;
  if (mPtr.z > 0. && length (mPtr.xy * vec2 (asp, 1.) - wgBxC.xy) > wgBxC.z) {
    az += 2. * pi * mPtr.x;
    el += pi * mPtr.y;
  }
  vuMat = StdVuMat (el, az);
  ro = vuMat * vec3 (0., 0., -5. * spRadB);
  //ro = vuMat * vec3 (0., 0., -5. * spRad);
  zmFac = 4.5 + 2. * abs (az);
  ltDir = vuMat * normalize (vec3 (1., 2., -1.));
#if ! AA
  const float naa = 1.;
#else
  const float naa = 3.;
#endif  
  col = vec3 (0.);
  sr = 2. * mod (dot (mod (floor (0.5 * (uv + 1.) * canvas), 2.), vec2 (1.)), 2.) - 1.;
  for (float a = 0.; a < naa; a ++) {
    uvv = uv + step (1.5, naa) * Rot2D (vec2 (0.5 / canvas.y, 0.), sr * (0.667 * a + 0.5) * pi);
    rd = vuMat * normalize (vec3 (uvv, zmFac));
    c = ShowScene (ro, rd);
    if (abs (length (0.5 * uvv - wgBxC.xy) - wgBxC.z) * canvas.y < 2.) c = vec3 (0.5, 0.8, 0.8);
    col += c / naa;
  }
  if (false && ShowInt (uv + vec2 (1.4, 0.9), 0.8 * vec2 (0.3, 0.08), 5., 1000. * kTemp) != 0.)
     col = vec3 (1., 1., 0.);
  fragColor = vec4 (col, 1.);
}

float Minv2 (vec2 p)
{
  return min (p.x, p.y);
}

float Maxv2 (vec2 p)
{
  return max (p.x, p.y);
}

vec2 Rot2D (vec2 q, float a)
{
  vec2 cs;
  cs = sin (a + vec2 (0.5 * pi, 0.));
  return vec2 (dot (q, vec2 (cs.x, - cs.y)), dot (q.yx, cs));
}

mat3 StdVuMat (float el, float az)
{
  vec2 ori, ca, sa;
  ori = vec2 (el, az);
  ca = cos (ori);
  sa = sin (ori);
  return mat3 (ca.y, 0., - sa.y, 0., 1., 0., sa.y, 0., ca.y) *
         mat3 (1., 0., 0., 0., ca.x, - sa.x, 0., sa.x, ca.x);
}

mat3 DirToRMatT (vec3 vd, vec3 vu)
{
  vec3 vc;
  vc = normalize (cross (vu, vd));
  return mat3 (vc, cross (vd, vc), vd);
}

vec3 HsvToRgb (vec3 c)
{
  return c.z * mix (vec3 (1.), clamp (abs (fract (c.xxx + vec3 (1., 2./3., 1./3.)) *
     6. - 3.) - 1., 0., 1.), c.y);
}

float DigSeg (vec2 q)
{
  q = 1. - smoothstep (vec2 (0.), vec2 (0.04, 0.07), abs (q) - vec2 (0.13, 0.5));
  return q.x * q.y;
}

#define DSG(q) k = kk;  kk = k / 2;  if (kk * 2 != k) d += DigSeg (q)

float ShowDig (vec2 q, int iv)
{
  vec2 vp, vm, vo;
  float d;
  int k, kk;
  vp = vec2 (0.5, 0.5);
  vm = vec2 (-0.5, 0.5);
  vo = vp - vm;
  if (iv == -1) k = 8;
  else if (iv < 2) k = (iv == 0) ? 119 : 36;
  else if (iv < 4) k = (iv == 2) ? 93 : 109;
  else if (iv < 6) k = (iv == 4) ? 46 : 107;
  else if (iv < 8) k = (iv == 6) ? 122 : 37;
  else             k = (iv == 8) ? 127 : 47;
  q = (q - 0.5) * vec2 (1.8, 2.3);
  d = 0.;
  kk = k;
  DSG (q.yx - vo);  DSG (q.xy - vp);  DSG (q.xy - vm);  DSG (q.yx);
  DSG (q.xy + vm);  DSG (q.xy + vp);  DSG (q.yx + vo);
  return d;
}

float ShowInt (vec2 q, vec2 cBox, float mxChar, float val)
{
  float nDig, idChar, s, sgn, v;
  q = vec2 (- q.x, q.y) / cBox;
  s = 0.;
  if (Minv2 (q) >= 0. && Maxv2 (q) < 1.) {
    q.x *= mxChar;
    sgn = sign (val);
    val = abs (val);
    nDig = (val > 0.) ? floor (max (log2 (val) / log2 (10.), 0.) + 0.0001) + 1. : 1.;
    idChar = mxChar - 1. - floor (q.x);
    q.x = fract (q.x);
    v = val / pow (10., mxChar - idChar - 1.);
    if (idChar == mxChar - nDig - 1. && sgn < 0.) s = ShowDig (q, -1);
    if (idChar >= mxChar - nDig) s = ShowDig (q, int (mod (floor (v), 10.)));
  }
  return s;
}

#define txBuf iChannel0
#define txSize iChannelResolution[0].xy

const float txRow = 128.;

vec4 Loadv4 (int idVar)
{
  float fi;
  fi = float (idVar);
  return texture (txBuf, (vec2 (mod (fi, txRow), floor (fi / txRow)) + 0.5) /
     txSize);
}

