float SmoothBump (float lo, float hi, float w, float x);
float Hashff (float p);
vec4 Loadv4 (int idVar);
void Savev4 (int idVar, vec4 val, inout vec4 fCol, vec2 fCoord);

const int lenChain = 800, lenBuf = 40;  // (integer multiple)
float tCur, spRad;
int nFrame;
const float txRow = 128.;
const float pi = 3.1415927;

void Step (int mId, out vec3 rm, out vec3 vm)
{
  vec3 rmN, rmN1, rmN2, dr, dr1, dr2, am;
  float fOvlap, fBend, rSep, c11, c22, c12, cd, c, dt;
  int k1, k2;
  fOvlap = 100.;
  fBend = 1000.;
  rm = Loadv4 (2 * mId).xyz;
  vm = Loadv4 (2 * mId + 1).xyz;
  am = vec3 (0.);
  for (int n = 0; n < lenChain; n ++) {
    if (n != mId) {
      rmN = Loadv4 (2 * n).xyz;
      dr = rm - rmN;
      rSep = length (dr);
      if (rSep < 1. || n == mId + 1 || n == mId - 1)
         am += fOvlap * (1. - rSep) * normalize (dr);
    }
  }
  for (int m = 0; m < 4; m ++) {
    if (m == 0 && mId <= 1 || (m == 1 || m == 2) && (mId == 0 || mId == lenChain - 1) ||
       m == 3 && mId >= lenChain - 2) continue;
    k1 = mId;
    k2 = mId;
    if (m == 0) {
      k1 -= 1;
      k2 -= 2;
    } else if (m == 1 || m == 2) {
      k1 -= 1;
      k2 += 1;
    } else if (m == 3) {
      k1 += 1;
      k2 += 2;
    }
    rmN1 = Loadv4 (2 * k1).xyz;
    rmN2 = Loadv4 (2 * k2).xyz;
    if (m == 0) {
      dr1 = rmN1 - rmN2;
      dr2 = rm - rmN1;
    } else if (m == 1 || m == 2) {
      dr1 = rm - rmN1;
      dr2 = rmN2 - rm;
    } else if (m == 3) {
      dr1 = rmN1 - rm;
      dr2 = rmN2 - rmN1;
    }
    c11 = dot (dr1, dr1);
    c12 = dot (dr1, dr2);
    c22 = dot (dr2, dr2);
    cd = sqrt (c11 * c22);
    c = c12 / cd - 1.;
    if (m == 0 || m == 3) c = - c;
    am += fBend * (c / cd) * ((m <= 1) ? dr1 - (c12 / c22) * dr2 : (c12 / c11) * dr1 - dr2);
  }  
  dr = rm - spRad * normalize (rm);
  rSep = length (dr);
  if (rSep < 1.) am += fOvlap * (1. - rSep) * normalize (dr);
  dt = 0.02;
  vm += dt * am;
  rm += dt * vm;
}

void Init (int mId, out vec3 rm, out vec3 vm)
{
  vec3 e;
  float mIdf, fn, r, a, h;
  mIdf = float (mId);
  r = 0.5 * spRad;
  h = -1.5 * (mIdf - 0.5 * float (lenChain)) / (2. * pi * r);
  a = 2. * pi * mod (0.9 * mIdf / (2. * pi * r), 1.);
  rm = vec3 (r * cos (a), h, r * sin (a));
  fn = mIdf + fract (tCur);
  vm = normalize (vec3 (Hashff (fn), Hashff (fn + 0.3), Hashff (fn + 0.6)) - 0.5);
}

void mainImage (out vec4 fragColor, in vec2 fragCoord)
{
  vec4 mPtr, mPtrP, stDat, tVal;
  vec3 rm, vm, wgBxC;
  vec2 canvas, iFrag;
  float nStep, asp, spRadB, kTemp, tRescale;
  int mId, pxId, bFirst;
  bool doInit;
  canvas = iResolution.xy;
  tCur = iTime;
  nFrame = iFrame;
  mPtr = iMouse;
  mPtr.xy = mPtr.xy / canvas - 0.5;
  iFrag = floor (fragCoord);
  pxId = int (iFrag.x + txRow * iFrag.y);
  if (iFrag.x >= txRow || pxId >= 2 * lenChain + 2 + lenBuf) discard;
  asp = canvas.x / canvas.y;
  wgBxC = vec3 (0.48 * asp, -0.46, 0.02);
  if (nFrame <= 1) {
    doInit = true;
    spRadB = float (lenChain) / 20.;
    spRad = spRadB;
    kTemp = 1.;
  } else {
    doInit = false;
    stDat = Loadv4 (2 * lenChain);
    nStep = stDat.x;
    spRad = stDat.y;
    spRadB = stDat.z;
    kTemp = stDat.w;
    ++ nStep;
  }
  mPtrP.z = Loadv4 (2 * lenChain + 1).z;
  if (mPtr.z > 0.) {
    if (length (mPtr.xy * vec2 (asp, 1.) - wgBxC.xy) < wgBxC.z) {
      if (mPtrP.z <= 0.) doInit = true;
    }
  }
  if (doInit) {
    nStep = 0.;
  }
  spRad = spRadB * (1. - 0.75 * SmoothBump (0.25, 0.75, 0.15, fract (nStep / 20000.)));
  tRescale = 50.;
  bFirst = 2 * lenChain + 2;
  if (pxId < 2 * lenChain) {
    mId = pxId / 2;
    if (doInit) Init (mId, rm, vm);
    else {
      Step (mId, rm, vm);
      if (mod (nStep, tRescale) == 2.) vm /= kTemp;
    }
    if      (pxId == 2 * mId) stDat = vec4 (rm, 0.);
    else if (pxId == 2 * mId + 1) stDat = vec4 (vm, 0.);
  } else if (pxId == 2 * lenChain) {
    if (mod (nStep, tRescale) == 1.) {
      tVal = vec4 (0.);
      for (int k = 0; k < lenChain / lenBuf; k ++) tVal += Loadv4 (bFirst + k);
      kTemp = sqrt (max (tVal.w / float (lenChain) - length (tVal.xyz) / float (lenChain), 0.));
    }
    stDat = vec4 (nStep, spRad, spRadB, kTemp);
  } else if (pxId == 2 * lenChain + 1) {
    stDat = vec4 (mPtr.xyz, 0.);
  } else if (pxId >= bFirst && pxId < bFirst + lenBuf) {
    if (mod (nStep, tRescale) == 0.) {
      tVal = vec4 (0.);
      for (int k = 0; k < lenBuf; k ++) {
        stDat = Loadv4 (2 * ((lenChain / lenBuf) * (pxId - bFirst) + k) + 1);
        tVal += vec4 (stDat.xyz, dot (stDat.xyz, stDat.xyz));
      }
      stDat = tVal;
    }
  }
  Savev4 (pxId, stDat, fragColor, fragCoord);
}

float SmoothBump (float lo, float hi, float w, float x)
{
  return (1. - smoothstep (hi - w, hi + w, x)) * smoothstep (lo - w, lo + w, x);
}

const float cHashM = 43758.54;

float Hashff (float p)
{
  return fract (sin (p) * cHashM);
}

#define txBuf iChannel0
#define txSize iChannelResolution[0].xy

vec4 Loadv4 (int idVar)
{
  float fi;
  fi = float (idVar);
  return texture (txBuf, (vec2 (mod (fi, txRow), floor (fi / txRow)) + 0.5) /
     txSize);
}

void Savev4 (int idVar, vec4 val, inout vec4 fCol, vec2 fCoord)
{
  vec2 d;
  float fi;
  fi = float (idVar);
  d = abs (fCoord - vec2 (mod (fi, txRow), floor (fi / txRow)) - 0.5);
  if (max (d.x, d.y) < 0.5) fCol = val;
}

